<title>Agent</title>
<script src=""></script>
<script src=""></script>
<link rel="stylesheet" href="">
<style>
*{box-sizing:border-box;margin:0;padding:0}
:root{
  --bg:#000;
  --glass:rgba(255,255,255,0.04);
  --glass2:rgba(255,255,255,0.07);
  --glass3:rgba(255,255,255,0.10);
  --border:rgba(255,255,255,0.07);
  --border2:rgba(255,255,255,0.12);
  --shadow:0 8px 32px rgba(0,0,0,0.8),inset 0 1px 0 rgba(255,255,255,0.05);
  --shadow2:0 16px 48px rgba(0,0,0,0.9),inset 0 1px 0 rgba(255,255,255,0.07);
  --text:#e8eaf0;--t2:#7a8299;--t3:#3a4055;--t4:#1e2235;
  --acc:#7c5cfc;--acc2:#a07fff;--glow:rgba(124,92,252,0.3);
  --grn:#22d35a;--grn-d:rgba(34,211,90,0.1);
  --red:#ff4d6a;--red-d:rgba(255,77,106,0.1);
  --yel:#f5a623;--yel-d:rgba(245,166,35,0.1);
  --blu:#3b9eff;--pur:#b06aff;--pur-d:rgba(176,106,255,0.1);
  --cyan:#00d4ff;
  --sw:252px;
}
html,body{height:100%;overflow:hidden;background:#000}
body{font-family:'Inter','SF Pro Display','Segoe UI',system-ui,sans-serif;background:#000;color:var(--text);display:flex}

::-webkit-scrollbar{width:3px;height:3px}
::-webkit-scrollbar-track{background:transparent}
::-webkit-scrollbar-thumb{background:rgba(255,255,255,0.08);border-radius:2px}

.g{background:var(--glass);backdrop-filter:blur(24px) saturate(180%);-webkit-backdrop-filter:blur(24px) saturate(180%);border:1px solid var(--border);box-shadow:var(--shadow)}
.g2{background:var(--glass2);backdrop-filter:blur(30px) saturate(200%);-webkit-backdrop-filter:blur(30px) saturate(200%);border:1px solid var(--border2);box-shadow:var(--shadow2)}

#sb{width:var(--sw);flex-shrink:0;display:flex;flex-direction:column;background:rgba(0,0,0,0.75);backdrop-filter:blur(40px) saturate(180%);-webkit-backdrop-filter:blur(40px) saturate(180%);border-right:1px solid var(--border);transition:width .22s cubic-bezier(.4,0,.2,1);overflow:hidden;position:relative;z-index:10}
#sb.col{width:0}
#sb::before{content:'';position:absolute;inset:0;background:linear-gradient(180deg,rgba(124,92,252,0.03) 0%,transparent 50%);pointer-events:none;z-index:0}

#sb-top{padding:13px 11px 9px;display:flex;align-items:center;gap:7px;border-bottom:1px solid var(--border);flex-shrink:0;position:relative;z-index:1}
#logo{width:24px;height:24px;background:linear-gradient(135deg,var(--acc),#4a3fcc,var(--cyan));border-radius:7px;display:flex;align-items:center;justify-content:center;font-size:12px;flex-shrink:0;box-shadow:0 0 14px var(--glow)}
.ib{background:none;border:none;cursor:pointer;color:var(--t3);padding:5px;border-radius:7px;display:flex;align-items:center;justify-content:center;transition:all .15s;flex-shrink:0}
.ib:hover{color:var(--t2);background:var(--glass2)}
.ib svg{width:14px;height:14px}

#nb{margin:9px 9px 5px;padding:8px 12px;background:linear-gradient(135deg,var(--acc),#4f3dd4);color:#fff;border:none;border-radius:9px;cursor:pointer;font-size:12px;font-weight:600;display:flex;align-items:center;gap:6px;transition:all .2s;box-shadow:0 4px 20px var(--glow);position:relative;z-index:1}
#nb:hover{transform:translateY(-1px);box-shadow:0 6px 28px var(--glow)}
#nb:active{transform:none}

#sb-tabs{display:flex;padding:5px 7px;gap:1px;border-bottom:1px solid var(--border);flex-shrink:0;position:relative;z-index:1}
.st{flex:1;padding:5px 2px;background:none;border:none;cursor:pointer;font-size:11px;color:var(--t3);border-radius:7px;transition:all .15s;display:flex;align-items:center;justify-content:center;gap:2px;white-space:nowrap;font-weight:500}
.st:hover{color:var(--t2);background:var(--glass)}
.st.on{color:var(--text);background:rgba(124,92,252,0.13);border:1px solid rgba(124,92,252,0.18)}
.badge{background:var(--acc);color:#fff;font-size:9px;padding:1px 4px;border-radius:6px;min-width:14px;text-align:center;font-weight:700}

#tc{flex:1;overflow-y:auto;overflow-x:hidden;position:relative;z-index:1}
.tp{display:none}
.tp.on{display:block}

#cl{padding:5px;display:flex;flex-direction:column;gap:1px}
.ci{padding:8px 10px;border-radius:8px;cursor:pointer;display:flex;align-items:center;gap:7px;transition:all .15s;min-width:0;position:relative}
.ci:hover{background:var(--glass)}
.ci.on{background:rgba(124,92,252,0.09);border:1px solid rgba(124,92,252,0.18)}
.ci.on::before{content:'';position:absolute;left:0;top:50%;transform:translateY(-50%);width:2px;height:55%;background:var(--acc);border-radius:0 2px 2px 0}
.ct{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11.5px;color:var(--t2)}
.ci.on .ct{color:var(--text)}
.sd{width:5px;height:5px;border-radius:50%;flex-shrink:0;transition:all .3s}
.sd.running{background:var(--grn);box-shadow:0 0 6px var(--grn);animation:gp 1.8s infinite}
.sd.paused{background:var(--yel)}
.sd.waiting,.sd.queued{background:var(--blu)}
.sd.done{background:var(--t4)}
.sd.failed{background:var(--red)}
@keyframes gp{0%,100%{opacity:1;box-shadow:0 0 6px var(--grn)}50%{opacity:.5;box-shadow:0 0 12px var(--grn)}}

#tp-tasks{padding:5px}
.tc{background:var(--glass);border:1px solid var(--border);border-radius:9px;margin-bottom:4px;cursor:pointer;transition:all .15s;overflow:hidden}
.tc:hover{border-color:var(--border2);background:var(--glass2)}
.tc.act{border-color:rgba(124,92,252,0.28);background:rgba(124,92,252,0.05)}
.tct{padding:7px 9px;display:flex;align-items:center;gap:6px}
.tpill{font-size:9px;padding:2px 6px;border-radius:20px;font-weight:700;flex-shrink:0}
.tpill.running{background:var(--grn-d);color:var(--grn);border:1px solid rgba(34,211,90,0.2)}
.tpill.paused{background:var(--yel-d);color:var(--yel);border:1px solid rgba(245,166,35,0.2)}
.tpill.done{background:rgba(255,255,255,0.03);color:var(--t3);border:1px solid var(--border)}
.tpill.failed{background:var(--red-d);color:var(--red);border:1px solid rgba(255,77,106,0.2)}
.tpill.waiting,.tpill.queued{background:rgba(59,158,255,0.08);color:var(--blu);border:1px solid rgba(59,158,255,0.18)}
.ttl{font-size:11px;color:var(--t2);flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.tab{display:flex;gap:2px;flex-shrink:0}
.tabtn{background:none;border:none;cursor:pointer;color:var(--t3);padding:3px 4px;border-radius:4px;font-size:11px;transition:all .12s}
.tabtn:hover{color:var(--t2);background:var(--glass2)}

#mp{padding:5px;display:flex;flex-direction:column;gap:3px}
.mc{background:var(--glass);border:1px solid var(--border);border-radius:8px;padding:8px 10px;transition:all .15s}
.mc:hover{border-color:var(--border2)}
.mk{font-size:10px;font-weight:700;color:var(--acc2);margin-bottom:3px;display:flex;align-items:center}
.mdel{margin-left:auto;background:none;border:none;cursor:pointer;color:var(--t3);font-size:12px;padding:0 3px;border-radius:3px;line-height:1;transition:all .12s}
.mdel:hover{color:var(--red)}
.mv{font-size:11px;color:var(--t2);line-height:1.5;word-break:break-word}
.mdate{font-size:9.5px;color:var(--t3);margin-top:3px}
#madd{margin:3px 5px;padding:7px;background:none;border:1px dashed rgba(124,92,252,0.2);border-radius:8px;color:var(--t3);cursor:pointer;font-size:11px;transition:all .15s;width:calc(100% - 10px)}
#madd:hover{border-color:var(--acc);color:var(--acc2);background:rgba(124,92,252,0.05)}

#nc{padding:10px 12px;font-size:11px;color:var(--t2);line-height:1.65;white-space:pre-wrap;word-break:break-word}

#qp{padding:5px;display:flex;flex-direction:column;gap:3px}
.qc{background:var(--glass);border:1px solid var(--border);border-radius:8px;padding:7px 10px;display:flex;align-items:center;gap:7px}
.qn{font-size:9.5px;background:rgba(59,158,255,0.1);color:var(--blu);padding:2px 6px;border-radius:7px;flex-shrink:0;font-weight:600}
.qp2{font-size:11px;color:var(--t2);flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}

#main{flex:1;display:flex;flex-direction:column;overflow:hidden;min-width:0;position:relative}

#tb{height:46px;padding:0 14px;border-bottom:1px solid var(--border);display:flex;align-items:center;gap:9px;background:rgba(0,0,0,0.6);backdrop-filter:blur(30px) saturate(180%);-webkit-backdrop-filter:blur(30px) saturate(180%);flex-shrink:0;position:relative;z-index:5}
#tb-title{font-size:13px;font-weight:600;color:var(--text);flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;letter-spacing:-.01em}
#timer{font-size:10.5px;color:var(--t3);font-variant-numeric:tabular-nums;display:none;white-space:nowrap;flex-shrink:0;background:var(--glass);border:1px solid var(--border);padding:2px 8px;border-radius:20px}
#timer.rt{color:var(--grn);border-color:rgba(34,211,90,0.2)}
#fbt{display:none;align-items:center;gap:4px;padding:4px 9px;background:var(--glass);border:1px solid var(--border);border-radius:7px;color:var(--t2);font-size:11px;cursor:pointer;transition:all .15s;flex-shrink:0}
#fbt:hover{border-color:var(--border2);color:var(--text)}

#pb{display:none;background:rgba(0,0,0,0.5);backdrop-filter:blur(20px);border-bottom:1px solid var(--border);padding:4px 14px;gap:5px;overflow-x:auto;flex-shrink:0}
#pb.vis{display:flex;align-items:center}
#pb::-webkit-scrollbar{height:2px}
.pch{display:flex;align-items:center;gap:5px;padding:3px 9px;background:var(--glass);border:1px solid var(--border);border-radius:20px;cursor:pointer;transition:all .15s;flex-shrink:0}
.pch:hover{border-color:var(--border2)}
.pch.ach{border-color:rgba(124,92,252,0.28);background:rgba(124,92,252,0.07)}
.pchd{width:5px;height:5px;border-radius:50%}
.pchd.running{background:var(--grn);animation:gp 1.8s infinite}
.pchd.paused{background:var(--yel)}
.pchd.done{background:var(--t4)}
.pchl{font-size:10.5px;color:var(--t2)}

#msgs{flex:1;overflow-y:auto;padding:22px 18px;display:flex;flex-direction:column;gap:16px;scroll-behavior:smooth}
.msg{display:flex;gap:11px;max-width:880px;width:100%;margin:0 auto}
.msg.usr{flex-direction:row-reverse}
.av{width:28px;height:28px;border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:12px;flex-shrink:0;margin-top:2px}
.av.ai{background:linear-gradient(135deg,var(--acc),#4f46e5,var(--cyan));box-shadow:0 0 14px var(--glow)}
.av.u{background:var(--glass2);border:1px solid var(--border2);font-size:9.5px;color:var(--t2)}
.bbl{flex:1;min-width:0;position:relative}
.msg.usr .bbl{display:flex;justify-content:flex-end}
.utxt{background:rgba(124,92,252,0.1);border:1px solid rgba(124,92,252,0.18);backdrop-filter:blur(12px);padding:9px 14px;border-radius:18px 18px 4px 18px;font-size:13.5px;line-height:1.65;max-width:78%;white-space:pre-wrap;word-break:break-word;color:var(--text)}
.hov{position:absolute;top:-1px;right:0;display:none;gap:2px;background:rgba(0,0,0,0.9);backdrop-filter:blur(16px);border:1px solid var(--border2);border-radius:7px;padding:3px;z-index:2}
.bbl:hover .hov{display:flex}
.hb{background:none;border:none;cursor:pointer;color:var(--t2);padding:3px 7px;border-radius:5px;font-size:11px;white-space:nowrap;transition:all .12s;display:flex;align-items:center;gap:3px}
.hb:hover{color:var(--text);background:var(--glass2)}

.aic{font-size:13.5px;line-height:1.78;color:var(--text)}
.aic p{margin-bottom:9px}.aic p:last-child{margin-bottom:0}
.aic h1,.aic h2,.aic h3{margin:13px 0 5px;color:var(--text);font-weight:700}
.aic h1{font-size:19px}.aic h2{font-size:16px}.aic h3{font-size:14px}
.aic ul,.aic ol{margin:5px 0 9px 18px}.aic li{margin-bottom:3px}
.aic a{color:var(--acc2);text-decoration:none}.aic a:hover{text-decoration:underline}
.aic blockquote{border-left:2px solid var(--acc);padding-left:11px;color:var(--t2);margin:9px 0;font-style:italic}
.aic table{border-collapse:collapse;width:100%;margin:9px 0;font-size:12.5px}
.aic th,.aic td{border:1px solid var(--border);padding:6px 10px}
.aic th{background:var(--glass2);font-weight:600}
.aic pre{margin:9px 0;border-radius:9px;overflow:hidden;border:1px solid var(--border);background:rgba(0,0,0,0.8)!important}
.aic pre code{padding:12px 14px;display:block;overflow-x:auto;font-size:12px;line-height:1.6;font-family:'Fira Code','Cascadia Code',Consolas,monospace}
.aic code:not(pre code){background:rgba(255,255,255,0.07);padding:2px 6px;border-radius:4px;font-size:12px;font-family:'Fira Code',Consolas,monospace}

.tbl{margin:4px 0;border:1px solid var(--border);border-radius:9px;overflow:hidden;background:rgba(0,0,0,0.55);backdrop-filter:blur(12px);transition:border-color .15s}
.tbl:hover{border-color:var(--border2)}
.thdr{padding:7px 11px;display:flex;align-items:center;gap:7px;cursor:pointer;user-select:none;transition:background .12s}
.thdr:hover{background:rgba(255,255,255,0.015)}
.tico{font-size:13px;flex-shrink:0}
.tnm{font-size:11.5px;font-weight:600;color:var(--t2)}
.tapv{font-size:10.5px;color:var(--t3);font-family:'Fira Code',Consolas,monospace;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:240px;margin-left:3px}
.tst{margin-left:auto;font-size:10px;display:flex;align-items:center;gap:3px;flex-shrink:0;padding:2px 7px;border-radius:20px}
.tst.run{color:var(--yel);background:var(--yel-d)}
.tst.dn{color:var(--grn);background:var(--grn-d)}
.tst.er{color:var(--red);background:var(--red-d)}
.tchv{color:var(--t3);font-size:9px;margin-left:3px;transition:transform .18s;flex-shrink:0}
.tbl.op .tchv{transform:rotate(180deg)}
.tdet{display:none;border-top:1px solid var(--border)}
.tbl.op .tdet{display:block}
.tar{padding:7px 11px;font-size:10.5px;font-family:'Fira Code',Consolas,monospace;color:var(--t3);white-space:pre-wrap;word-break:break-all;max-height:72px;overflow-y:auto;border-bottom:1px solid var(--border)}
.trr pre{margin:0;padding:9px 12px;font-size:11px;font-family:'Fira Code',Consolas,monospace;color:#7a8fa8;white-space:pre-wrap;word-break:break-word;max-height:240px;overflow-y:auto;line-height:1.5}

.injpill{display:inline-flex;align-items:center;gap:6px;background:rgba(176,106,255,0.07);border:1px solid rgba(176,106,255,0.18);color:#c084fc;padding:5px 11px;border-radius:7px;font-size:11.5px;margin:3px 0}
.thr{display:flex;align-items:center;gap:9px;color:var(--t3);font-size:13px;padding:3px 0}
.thdots{display:flex;gap:4px}
.thd{width:4px;height:4px;background:var(--t3);border-radius:50%;animation:tb .9s ease-in-out infinite}
.thd:nth-child(2){animation-delay:.15s}.thd:nth-child(3){animation-delay:.3s}
@keyframes tb{0%,80%,100%{transform:translateY(0);opacity:.3}40%{transform:translateY(-5px);opacity:1}}

.est{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:14px;text-align:center;padding:48px 28px;max-width:480px;margin:0 auto;width:100%;height:100%}
.eico{width:56px;height:56px;background:linear-gradient(135deg,var(--acc),#4f46e5,var(--cyan));border-radius:50%;display:flex;align-items:center;justify-content:center;font-size:24px;box-shadow:0 0 28px var(--glow),0 0 56px rgba(0,212,255,0.07)}
.eb{background:rgba(255,77,106,0.07);border:1px solid rgba(255,77,106,0.18);color:#ff8fa0;padding:8px 12px;border-radius:8px;font-size:12px;margin:3px 0;line-height:1.5}

#ia{padding:9px 18px 15px;background:rgba(0,0,0,0.4);backdrop-filter:blur(24px);flex-shrink:0;position:relative;z-index:5}

#pb2{display:none;max-width:880px;margin:0 auto 7px;background:rgba(245,166,35,0.06);border:1px solid rgba(245,166,35,0.18);color:#fcd34d;padding:7px 13px;border-radius:9px;font-size:12px;align-items:center;gap:8px}
#pb2 .pp{width:6px;height:6px;border-radius:50%;background:var(--yel);flex-shrink:0;animation:gp 1.5s infinite}
#rb{background:rgba(34,211,90,0.1);border:1px solid rgba(34,211,90,0.22);color:var(--grn);padding:3px 10px;border-radius:6px;cursor:pointer;font-size:11.5px;font-weight:600;transition:all .15s}
#rb:hover{background:rgba(34,211,90,0.2)}

#inj{display:none;max-width:880px;margin:0 auto 7px}
#injg{display:flex;align-items:center;gap:7px;background:rgba(176,106,255,0.05);border:1px solid rgba(176,106,255,0.18);border-radius:10px;padding:6px 9px 6px 13px;backdrop-filter:blur(14px);transition:border-color .15s}
#injg:focus-within{border-color:rgba(176,106,255,0.38)}
#injl{font-size:10.5px;color:var(--pur);font-weight:700;white-space:nowrap;display:flex;align-items:center;gap:4px}
#injin{flex:1;background:none;border:none;outline:none;color:var(--text);font-size:13px;font-family:inherit;padding:0}
#injin::placeholder{color:var(--t3)}
#injsend{background:rgba(176,106,255,0.12);border:1px solid rgba(176,106,255,0.22);color:var(--pur);padding:3px 10px;border-radius:6px;cursor:pointer;font-size:11.5px;font-weight:600;transition:all .15s;white-space:nowrap;flex-shrink:0}
#injsend:hover{background:rgba(176,106,255,0.25)}

.upl{max-width:880px;margin:0 auto 5px;display:flex;flex-wrap:wrap;gap:4px}
.uch{display:flex;align-items:center;gap:4px;background:rgba(59,158,255,0.07);border:1px solid rgba(59,158,255,0.18);border-radius:6px;padding:3px 8px;font-size:11px;color:var(--blu)}
.ucn{max-width:110px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.ucrm{background:none;border:none;cursor:pointer;color:var(--blu);font-size:12px;line-height:1;padding:0 0 0 2px;opacity:.6;transition:opacity .12s}
.ucrm:hover{opacity:1}

#ig{max-width:880px;margin:0 auto;background:rgba(0,0,0,0.7);backdrop-filter:blur(30px) saturate(180%);-webkit-backdrop-filter:blur(30px) saturate(180%);border:1px solid var(--border2);border-radius:13px;display:flex;align-items:flex-end;gap:5px;padding:7px 7px 7px 14px;transition:border-color .18s,box-shadow .18s;box-shadow:0 4px 24px rgba(0,0,0,0.5)}
#ig:focus-within{border-color:rgba(124,92,252,0.42);box-shadow:0 4px 32px rgba(124,92,252,0.12),0 0 0 1px rgba(124,92,252,0.08)}
#inp{flex:1;background:none;border:none;outline:none;color:var(--text);font-size:13.5px;font-family:inherit;resize:none;max-height:160px;min-height:22px;line-height:1.65;padding:1px 0}
#inp::placeholder{color:var(--t3)}

.ibtn{width:32px;height:32px;border:1px solid var(--border);background:var(--glass);border-radius:8px;cursor:pointer;display:none;align-items:center;justify-content:center;flex-shrink:0;transition:all .18s;color:var(--t2)}
.ibtn:hover{border-color:var(--border2);background:var(--glass2)}
.ibtn.sh{display:flex}
#upbtn{display:flex;width:32px;height:32px;border:1px solid var(--border);background:var(--glass);border-radius:8px;cursor:pointer;align-items:center;justify-content:center;flex-shrink:0;transition:all .18s;color:var(--t2)}
#upbtn:hover{border-color:rgba(124,92,252,0.3);background:rgba(124,92,252,0.05);color:var(--acc2)}
#fi{display:none}
#pbtn:hover{border-color:rgba(245,166,35,0.3);color:var(--yel);background:var(--yel-d)}
#rebtn:hover{border-color:rgba(34,211,90,0.3);color:var(--grn);background:var(--grn-d)}
#sbtn:hover{border-color:rgba(255,77,106,0.3);color:var(--red);background:var(--red-d)}
#sendbtn{width:32px;height:32px;background:linear-gradient(135deg,var(--acc),#5b3fd4);border:none;border-radius:8px;cursor:pointer;display:flex;align-items:center;justify-content:center;flex-shrink:0;transition:all .18s;box-shadow:0 2px 12px var(--glow)}
#sendbtn:hover:not(:disabled){transform:translateY(-1px);box-shadow:0 4px 20px var(--glow)}
#sendbtn:disabled{opacity:.25;cursor:not-allowed;transform:none;box-shadow:none}

#sm{display:none;position:fixed;inset:0;background:rgba(0,0,0,0.7);backdrop-filter:blur(12px);z-index:200;align-items:flex-start;justify-content:center;padding-top:72px}
#sm.op{display:flex}
#sb2{background:rgba(0,0,0,0.92);backdrop-filter:blur(40px);border:1px solid var(--border2);border-radius:13px;width:600px;max-width:90vw;overflow:hidden;box-shadow:0 24px 64px rgba(0,0,0,0.9)}
#smt{display:flex;align-items:center;gap:9px;padding:13px 15px;border-bottom:1px solid var(--border)}
#smi{flex:1;background:none;border:none;outline:none;color:var(--text);font-size:14px;font-family:inherit}
#smi::placeholder{color:var(--t3)}
#sr{max-height:400px;overflow-y:auto}
.sh{padding:11px 15px;cursor:pointer;border-bottom:1px solid var(--border);transition:background .12s}
.sh:hover{background:var(--glass)}
.sht{font-size:13px;color:var(--text);margin-bottom:3px;font-weight:500}
.shp{font-size:11px;color:var(--t3);font-family:'Fira Code',Consolas,monospace;white-space:pre-wrap;word-break:break-word;line-height:1.4}
.shm{font-size:10px;color:var(--t3);margin-top:3px}
#se{padding:28px;text-align:center;color:var(--t3);font-size:13px}
</style>
</head>
<body>

<div id="sb" class="col">
  <div id="sb-top">
    <div id="logo">✦</div>
    <button class="ib" onclick="openSearch()" title="Search (Ctrl+K)">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="8"></circle><line x1="21" y1="21" x2="16.65" y2="16.65"></line></svg>
    </button>
  </div>
  <button id="nb" onclick="newChat()">
    <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5"><line x1="12" y1="5" x2="12" y2="19"></line><line x1="5" y1="12" x2="19" y2="12"></line></svg>
    New task
  </button>
  <div id="sb-tabs">
    <button class="st on" data-tab="chats" onclick="sw('chats')">💬</button>
    <button class="st" data-tab="tasks" onclick="sw('tasks')">⚡ <span class="badge" id="rbadge" style="display:none">0</span></button>
    <button class="st" data-tab="memory" onclick="sw('memory');loadMem()">🧠</button>
    <button class="st" data-tab="notes" onclick="sw('notes');loadNotes()">📝</button>
    <button class="st" data-tab="queue" onclick="sw('queue');loadQueue()">🗂</button>
  </div>
  <div id="tc">
    <div class="tp on" id="tp-chats"><div id="cl"></div></div>
    <div class="tp" id="tp-tasks"><div id="tp-tasks-inner"><div style="padding:18px;text-align:center;color:var(--t3);font-size:12px">No tasks yet</div></div></div>
    <div class="tp" id="tp-memory">
      <div id="mp"></div>
      <button id="madd" onclick="addMem()">+ Add entry</button>
    </div>
    <div class="tp" id="tp-notes"><div id="nc">Loading…</div></div>
    <div class="tp" id="tp-queue"><div id="qp"></div></div>
  </div>
</div>

<div id="main">
  <div id="tb">
    <button class="ib" onclick="toggleSB()">
      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="3" y1="6" x2="21" y2="6"></line><line x1="3" y1="12" x2="21" y2="12"></line><line x1="3" y1="18" x2="21" y2="18"></line></svg>
    </button>
    <span id="tb-title">Agent</span>
    <span id="timer"></span>
    <button id="fbt" onclick="forkAll()">
      <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="5" r="3"></circle><circle cx="5" cy="19" r="3"></circle><circle cx="19" cy="19" r="3"></circle><line x1="12" y1="8" x2="12" y2="13"></line><line x1="12" y1="13" x2="5" y2="16"></line><line x1="12" y1="13" x2="19" y2="16"></line></svg>
      Fork
    </button>
  </div>

  <div id="pb"></div>
  <div id="msgs"><div class="est" id="est"><div class="eico">✦</div></div></div>

  <div id="ia">
    <div id="pb2">
      <div class="pp"></div>
      <span style="flex:1">Paused — resumes exactly where it stopped.</span>
      <button id="rb" onclick="doResume()">▶ Resume</button>
    </div>
    <div id="inj">
      <div id="injg">
        <span id="injl">⚡ Inject</span>
        <input id="injin" placeholder="Redirect the agent mid-task…">
        <button id="injsend" onclick="sendInj()">Send →</button>
      </div>
    </div>
    <div class="upl" id="upl"></div>
    <div id="ig">
      <textarea id="inp" placeholder="Give the agent a task…" rows="1"></textarea>
      <input type="file" id="fi" multiple="" onchange="handleFiles(this)">
      <button id="upbtn" onclick="document.getElementById('fi').click()" title="Attach files">
        <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21.44 11.05l-9.19 9.19a6 6 0 01-8.49-8.49l9.19-9.19a4 4 0 015.66 5.66l-9.2 9.19a2 2 0 01-2.83-2.83l8.49-8.48"></path></svg>
      </button>
      <button id="pbtn" class="ibtn" onclick="doPause()" title="Pause">
        <svg width="11" height="11" viewBox="0 0 24 24" fill="currentColor"><rect x="6" y="4" width="4" height="16" rx="1"></rect><rect x="14" y="4" width="4" height="16" rx="1"></rect></svg>
      </button>
      <button id="rebtn" class="ibtn" onclick="doResume()" title="Resume">
        <svg width="11" height="11" viewBox="0 0 24 24" fill="currentColor"><polygon points="5,3 19,12 5,21"></polygon></svg>
      </button>
      <button id="sbtn" class="ibtn" onclick="doStop()" title="Stop">
        <svg width="10" height="10" viewBox="0 0 24 24" fill="currentColor"><rect x="4" y="4" width="16" height="16" rx="2"></rect></svg>
      </button>
      <button id="sendbtn" onclick="send()">
        <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="white" stroke-width="2.5"><line x1="12" y1="19" x2="12" y2="5"></line><polyline points="5 12 12 5 19 12"></polyline></svg>
      </button>
    </div>
  </div>
</div>

<div id="sm" onclick="if(event.target===this)closeSrch()">
  <div id="sb2">
    <div id="smt">
      <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="var(--t3)" stroke-width="2"><circle cx="11" cy="11" r="8"></circle><line x1="21" y1="21" x2="16.65" y2="16.65"></line></svg>
      <input id="smi" placeholder="Search past sessions…" oninput="doSrch(this.value)">
      <button class="ib" onclick="closeSrch()">✕</button>
    </div>
    <div id="sr"><div id="se">Type to search past sessions</div></div>
  </div>
</div>

<script>
if('serviceWorker' in navigator){navigator.serviceWorker.register('/sw.js').catch(()=>{});}

marked.setOptions({breaks:true,gfm:true});
const ICONS={bash:'💻',read_file:'📄',write_file:'✏️',edit_file:'🔧',list_directory:'📁',glob:'🔍',grep:'🔎',delete_file:'🗑️',move_file:'📦',web_search:'🌐',web_fetch:'🌍',screenshot_url:'📸',database_query:'🗄️',http_request:'📡',view_env_vars:'🔑',git_operation:'🌿',spawn_subagent:'🤖',memory_read:'🧠',memory_write:'💾',agent_note:'📝'};

let convs=JSON.parse(localStorage.getItem('ag_v1')||'[]');
let aid=null,running=false,paused=false,atid=null;
let aSSE=null,timerIv=null,tStart=null,pollIv=null,stopped=false;
let srchTmr=null,allTasks={},uploads=[];

const $=id=>document.getElementById(id);
function save(){localStorage.setItem('ag_v1',JSON.stringify(convs))}
function gc(id){return convs.find(c=>c.id===id)}
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function uid(){return Date.now().toString(36)+Math.random().toString(36).slice(2)}
function scrl(){const m=$('msgs');m.scrollTop=m.scrollHeight}

function newChat(){
  const id=uid();
  convs.unshift({id,title:'New task',messages:[],taskId:null,created:Date.now()});
  save();loadConv(id);
}

function loadConv(id){
  aid=id;
  const c=gc(id),el=$('msgs');
  el.innerHTML='';
  if(!c.messages.length)showEmpty();
  else{c.messages.forEach(m=>{if(m.role==='user')renderU(m.content,false);else renderA(m.content,m.tools||[],false,m.mid);});scrl();}
  $('tb-title').textContent=c.title||'Agent';
  renderSB();updPB();
}

function sw(tab){
  document.querySelectorAll('.st').forEach(b=>b.classList.toggle('on',b.dataset.tab===tab));
  document.querySelectorAll('.tp').forEach(p=>p.classList.toggle('on',p.id===`tp-${tab}`));
}

function renderSB(){
  const el=$('cl');el.innerHTML='';
  convs.forEach(c=>{
    const t=c.taskId?allTasks[c.taskId]:null;
    const st=t?(t.paused?'paused':t.status):'done';
    const d=document.createElement('div');
    d.className='ci'+(c.id===aid?' on':'');
    d.innerHTML=`<div class="sd ${st}"></div><div class="ct">${esc(c.title||'New task')}</div>`;
    d.onclick=()=>{if(c.id!==aid){doStop();loadConv(c.id);}};
    el.appendChild(d);
  });
}

function renderTasks(){
  const el=$('tp-tasks-inner');el.innerHTML='';
  const all=Object.entries(allTasks).sort((a,b)=>b[1].created-a[1].created);
  const running=all.filter(([,t])=>!['done','failed','cancelled'].includes(t.status));
  const badge=$('rbadge');
  badge.textContent=running.length;badge.style.display=running.length?'inline':'none';
  all.slice(0,30).forEach(([tid,t])=>{
    const st=t.paused?'paused':t.status;
    const conv=convs.find(c=>c.taskId===tid);
    const card=document.createElement('div');
    card.className='tc'+(tid===atid?' act':'');
    card.innerHTML=`<div class="tct">
      <span class="tpill ${st}">${st.toUpperCase()}</span>
      <span class="ttl">${esc(t.title||tid.slice(0,12))}</span>
      <div class="tab">
        ${st==='running'?`<button class="tabtn" title="Pause" onclick="event.stopPropagation();aPause('${tid}')">⏸</button>`:''}
        ${st==='paused'?`<button class="tabtn" title="Resume" onclick="event.stopPropagation();aResume('${tid}')">▶</button>`:''}
        ${['running','paused'].includes(st)?`<button class="tabtn" title="Cancel" onclick="event.stopPropagation();aCancel('${tid}')">✕</button>`:''}
      </div>
    </div>`;
    if(conv)card.onclick=()=>{doStop();loadConv(conv.id);};
    el.appendChild(card);
  });
  if(!all.length)el.innerHTML='<div style="padding:18px;text-align:center;color:var(--t3);font-size:12px">No tasks yet</div>';
}

async function pollAll(){
  try{
    const r=await fetch('/api/tasks');if(!r.ok)return;
    const list=await r.json();
    allTasks={};list.forEach(t=>{allTasks[t.task_id]=t;});
    renderTasks();renderSB();updPB();
  }catch{}
}
setInterval(pollAll,3000);

function updPB(){
  const bar=$('pb');
  const run=Object.entries(allTasks).filter(([,t])=>['running','paused'].includes(t.paused?'paused':t.status));
  if(run.length<=1){bar.classList.remove('vis');bar.innerHTML='';return;}
  bar.classList.add('vis');bar.innerHTML='';
  run.forEach(([tid,t])=>{
    const dot=t.paused?'paused':t.status==='running'?'running':'done';
    const ch=document.createElement('div');
    ch.className='pch'+(tid===atid?' ach':'');
    ch.innerHTML=`<div class="pchd ${dot}"></div><span class="pchl">${esc((t.title||tid).slice(0,26))}</span>`;
    const conv=convs.find(c=>c.taskId===tid);
    if(conv)ch.onclick=()=>{doStop();loadConv(conv.id);};
    bar.appendChild(ch);
  });
}

async function aPause(tid){await fetch(`/api/task/${tid}/pause`,{method:'POST'});if(tid===atid)setPaused(true);}
async function aResume(tid){await fetch(`/api/task/${tid}/resume`,{method:'POST'});if(tid===atid)setPaused(false);}
async function aCancel(tid){if(!confirm('Cancel this task?'))return;await fetch(`/api/task/${tid}/cancel`,{method:'POST'});}

function showEmpty(){
  const el=$('msgs');
  if($('est'))return;
  const e=document.createElement('div');e.className='est';e.id='est';
  e.innerHTML=`<div class="eico">✦</div>`;
  el.appendChild(e);
}
function rmEmpty(){const e=$('est');if(e)e.remove();}

function renderU(text,scroll=true){
  rmEmpty();
  const el=document.createElement('div');el.className='msg usr';
  el.innerHTML=`<div class="av u">You</div><div class="bbl"><div class="utxt">${esc(text)}</div></div>`;
  $('msgs').appendChild(el);
  if(scroll)scrl();
}

function renderA(text,tools,scroll=true,msgId){
  const el=document.createElement('div');el.className='msg';
  if(msgId)el.dataset.mid=msgId;
  el.dataset.idx=document.querySelectorAll('.msg').length;
  const th=(tools||[]).map(t=>mkTB(t)).join('');
  el.innerHTML=`<div class="av ai">✦</div><div class="bbl">${th}<div class="aic">${marked.parse(text||'')}</div><div class="hov">
    <button class="hb" onclick="forkHere(this)">⎇ Fork</button>
    <button class="hb" onclick="copyHere(this)">⎘ Copy</button>
  </div></div>`;
  el.querySelectorAll('pre code').forEach(b=>hljs.highlightElement(b));
  $('msgs').appendChild(el);
  if(scroll)scrl();
}

function mkTB(t){
  const icon=ICONS[t.name]||'⚙️';
  const prev=tPrev(t.name,t.args||{});
  const isErr=t.error||false;
  const sCls=isErr?'er':'dn';const sTxt=isErr?'✗ Error':'✓ Done';
  const ah=prev?`<div class="tar">${esc(prev)}</div>`:'';
  const rh=t.result?`<div class="trr"><pre>${esc(t.result)}</pre></div>`:'';
  return `<div class="tbl"><div class="thdr" onclick="this.parentElement.classList.toggle('op')"><span class="tico">${icon}</span><span class="tnm">${t.name}</span>${prev?`<span class="tapv">${esc(prev.slice(0,50))}</span>`:''}<span class="tst ${sCls}">${sTxt}</span><span class="tchv">▼</span></div><div class="tdet">${ah}${rh}</div></div>`;
}

function tPrev(name,args){
  const m={bash:'command',read_file:'path',write_file:'path',edit_file:'path',delete_file:'path',list_directory:'path',glob:'pattern',grep:'pattern',web_search:'query',web_fetch:'url',screenshot_url:'url',git_operation:'command',agent_note:'note',spawn_subagent:'task',memory_write:'key',memory_read:'key'};
  if(m[name]&&args[m[name]])return String(args[m[name]]);
  if(name==='move_file')return `${args.source||''} → ${args.destination||''}`;
  if(name==='http_request')return `${args.method||'GET'} ${args.url||''}`;
  if(name==='database_query')return String(args.sql||'').slice(0,80);
  return JSON.stringify(args).slice(0,80);
}

function forkHere(btn){
  const msgEl=btn.closest('.msg');
  const idx=parseInt(msgEl.dataset.idx||'0');
  const p=prompt('Fork from this point — new direction:');
  if(!p||!aid)return;
  const c=gc(aid);if(!c||!c.taskId)return alert('No task ID.');
  fetch(`/api/task/${c.taskId}/fork`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message_index:idx,message:p})})
    .then(r=>r.json()).then(d=>{if(d.task_id)mkFork(d.task_id,p);});
}

function forkAll(){
  const c=gc(aid);if(!c||!c.taskId)return alert('No completed task to fork.');
  const p=window.prompt('Fork from end — new direction:');if(!p)return;
  fetch(`/api/task/${c.taskId}/fork`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:p})})
    .then(r=>r.json()).then(d=>{if(d.task_id)mkFork(d.task_id,p);else alert('Fork failed: '+JSON.stringify(d));});
}

function mkFork(taskId,p){
  const fid=uid();
  convs.unshift({id:fid,title:'Fork: '+p.slice(0,45),messages:[],taskId,created:Date.now()});
  save();loadConv(fid);startListen(taskId);setRunning(true);
}

function copyHere(btn){
  const c=btn.closest('.bbl').querySelector('.aic');
  if(c)navigator.clipboard.writeText(c.innerText).catch(()=>{});
}

function startTimer(){
  tStart=Date.now();const el=$('timer');
  el.style.display='block';el.className='rt';
  if(timerIv)clearInterval(timerIv);
  timerIv=setInterval(()=>{const s=Math.floor((Date.now()-tStart)/1000);el.textContent=`${Math.floor(s/60)}:${(s%60).toString().padStart(2,'0')}`;},1000);
}
function stopTimer(){if(timerIv)clearInterval(timerIv);timerIv=null;$('timer').style.display='none';}

function setRunning(v){
  running=v;if(!v)paused=false;
  $('sendbtn').disabled=v;
  $('sbtn').classList.toggle('sh',v);
  $('pbtn').classList.toggle('sh',v&&!paused);
  $('rebtn').classList.toggle('sh',v&&paused);
  $('inj').style.display=v?'block':'none';
  $('pb2').style.display='none';
  $('fbt').style.display=!v&&aid&&gc(aid)?.taskId?'flex':'none';
  if(v)startTimer();else stopTimer();
  renderSB();
}

function setPaused(v){
  paused=v;
  $('pbtn').classList.toggle('sh',running&&!v);
  $('rebtn').classList.toggle('sh',running&&v);
  $('pb2').style.display=v?'flex':'none';
}

async function doPause(){if(!atid)return;await fetch(`/api/task/${atid}/pause`,{method:'POST'});}
async function doResume(){if(!atid)return;await fetch(`/api/task/${atid}/resume`,{method:'POST'});}

function doStop(){
  stopped=true;
  if(aSSE){aSSE.close();aSSE=null;}
  if(pollIv){clearInterval(pollIv);pollIv=null;}
  if(atid)fetch(`/api/task/${atid}/cancel`,{method:'POST'}).catch(()=>{});
  atid=null;setRunning(false);setPaused(false);
  const b=$('live-bbl');if(b){b.querySelector('.thr')?.remove();b.id='';}
}

async function sendInj(){
  const inp=$('injin'),msg=inp.value.trim();
  if(!msg||!atid)return;inp.value='';
  const r=await fetch(`/api/task/${atid}/inject`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:msg})});
  if(!r.ok){const d=await r.json();alert(d.error||'Inject failed');}
}

async function handleFiles(input){
  const files=Array.from(input.files);if(!files.length)return;
  const form=new FormData();files.forEach(f=>form.append('file',f));
  const upl=$('upl');
  const phs=files.map(f=>{const ch=document.createElement('div');ch.className='uch';ch.innerHTML=`<span class="ucn">${esc(f.name)}</span><span style="color:var(--yel);font-size:10px">…</span>`;upl.appendChild(ch);return ch;});
  try{
    const r=await fetch('/api/upload',{method:'POST',body:form});
    const d=await r.json();phs.forEach(c=>c.remove());
    if(d.saved){d.saved.forEach(s=>{const ch=document.createElement('div');ch.className='uch';ch.innerHTML=`<span class="ucn">${esc(s.filename)}</span><button class="ucrm" onclick="rmUp(this,'${esc(s.path)}')">✕</button>`;upl.appendChild(ch);uploads.push(s);});}
    if(d.errors?.length)alert('Upload errors:\n'+d.errors.join('\n'));
  }catch(e){phs.forEach(c=>c.remove());alert('Upload failed: '+e.message);}
  input.value='';
}

function rmUp(btn,path){uploads=uploads.filter(u=>u.path!==path);btn.closest('.uch').remove();}

async function send(){
  const input=$('inp');let text=input.value.trim();
  if(!text&&!uploads.length)return;if(running)return;
  if(uploads.length){
    const fl=uploads.map(u=>`- ${u.path} (${u.size} bytes)`).join('\n');
    text=(text?text+'\n\n':'')+'Uploaded files:\n'+fl;
    uploads=[];$('upl').innerHTML='';
  }
  input.value='';resize(input);stopped=false;
  if(!aid)newChat();
  const c=gc(aid),mid=uid();
  c.messages.push({role:'user',content:text,mid});
  if(c.messages.filter(m=>m.role==='user').length===1)c.title=text.slice(0,52)+(text.length>52?'…':'');
  save();renderSB();
  renderU(text,false);setRunning(true);
  const live=document.createElement('div');live.className='msg';
  live.innerHTML=`<div class="av ai">✦</div><div class="bbl" id="live-bbl"><div class="thr"><div class="thdots"><div class="thd"></div><div class="thd"></div><div class="thd"></div></div><span>Working…</span></div></div>`;
  $('msgs').appendChild(live);scrl();
  const apiMsgs=c.messages.map(m=>({role:m.role==='assistant'?'assistant':'user',content:m.content}));
  let taskId;
  try{
    const resp=await fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:apiMsgs,title:c.title,load_context:true})});
    if(!resp.ok){const d=await resp.json();finBbl(`Error: ${d.error||'Failed to start'}`);return;}
    const d=await resp.json();taskId=d.task_id;atid=taskId;c.taskId=taskId;save();
  }catch(e){finBbl(`Connection error: ${e.message}`);return;}
  startListen(taskId);
}

function startListen(taskId){
  const bbl=$('live-bbl');
  const tblks={};let txtBuf='';let txtEl=null;
  let tSave=[];let pollCur=0;

  function proc(ev){
    if(stopped)return;
    const thinking=bbl?.querySelector('.thr');
    if(ev.type==='text_delta'){
      thinking?.remove();
      if(!txtEl){txtEl=document.createElement('div');txtEl.className='aic';bbl?.appendChild(txtEl);}
      txtBuf+=ev.delta;
