## 2. `sw.js` — Service Worker (cache, offline, background sync, push)

```js
const CACHE = 'agent-v2';
const PRECACHE = ['/', '/index.html', '/manifest.json', '/offline.html',
  '/icons/icon-192.png', '/icons/icon-512.png'];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(PRECACHE)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(keys =>
    Promise.all(keys.filter(k => k !== CACHE).map(k => caches.delete(k)))
  ).then(() => self.clients.claim()));
});

// Stale-while-revalidate + cache-first
self.addEventListener('fetch', e => {
  if (e.request.method !== 'GET') return;
  if (e.request.url.includes('/api/')) {
    // network-first for API
    e.respondWith(fetch(e.request).catch(() => caches.match(e.request)));
    return;
  }
  e.respondWith(
    caches.match(e.request).then(cached => {
      const fresh = fetch(e.request).then(resp => {
        if (resp && resp.status === 200) {
          const clone = resp.clone();
          caches.open(CACHE).then(c => c.put(e.request, clone));
        }
        return resp;
      });
      return cached || fresh.catch(() => caches.match('/offline.html'));
    })
  );
});

// Background Sync
self.addEventListener('sync', e => {
  if (e.tag === 'send-message') {
    e.waitUntil(syncPendingMessages());
  }
});

async function syncPendingMessages() {
  const db = await openDB();
  const tx = db.transaction('pending', 'readwrite');
  const all = await tx.objectStore('pending').getAll();
  for (const item of all) {
    try {
      await fetch('/api/chat', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify(item) });
      await tx.objectStore('pending').delete(item.id);
    } catch {}
  }
}

// Push notifications (Declarative Web Push + classic)
self.addEventListener('push', e => {
  const data = e.data?.json() || {};
  e.waitUntil(
    self.registration.showNotification(data.title || 'Agent', {
      body: data.body || 'Task update',
      icon: '/icons/icon-192.png',
      badge: '/icons/badge-96.png',
      vibrate: [100, 50, 100],
      data: { url: data.url || '/' },
      actions: [
        { action: 'open', title: 'Open', icon: '/icons/action-open.png' },
        { action: 'dismiss', title: 'Dismiss' }
      ],
      tag: data.tag || 'agent-notif',
      renotify: true,
      requireInteraction: false
    })
  );
});

self.addEventListener('notificationclick', e => {
  e.notification.close();
  if (e.action === 'dismiss') return;
  const url = e.notification.data?.url || '/';
  e.waitUntil(
    clients.matchAll({ type: 'window' }).then(list => {
      for (const c of list) { if (c.url.includes(self.location.origin)) { c.focus(); c.navigate(url); return; } }
      return clients.openWindow(url);
    })
  );
});

// Periodic background sync
self.addEventListener('periodicsync', e => {
  if (e.tag === 'poll-tasks') {
    e.waitUntil(fetch('/api/tasks').catch(() => {}));
  }
});

// Handle share target POST
self.addEventListener('fetch', e => {
  if (e.request.url.includes('/share') && e.request.method === 'POST') {
    e.respondWith((async () => {
      const fd = await e.request.formData();
      const client = await clients.get(e.resultingClientId);
      client?.postMessage({ type: 'share', title: fd.get('title'), text: fd.get('text'), url: fd.get('url') });
      return Response.redirect('/', 303);
    })());
  }
});

function openDB() {
  return new Promise((res, rej) => {
    const req = indexedDB.open('agent-sw', 1);
    req.onupgradeneeded = e => e.target.result.createObjectStore('pending', { keyPath: 'id' });
    req.onsuccess = e => res(e.target.result);
    req.onerror = e => rej(e);
  });
}
```

