    const n = document.createElement('div');
    n.id = 'offline-toast';
    n.style = 'position:fixed;top:calc(10px + env(safe-area-inset-top));left:50%;transform:translateX(-50%);background:rgba(255,77,106,0.15);border:1px solid rgba(255,77,106,0.3);color:#ff8fa0;padding:8px 16px;border-radius:20px;font-size:12px;z-index:9999;backdrop-filter:blur(20px)';
    n.textContent = '⚠️ Offline — messages queued';
    document.body.appendChild(n);
  } else { document.getElementById('offline-toast')?.remove(); }
}
window.addEventListener('online', updateOnlineStatus);
window.addEventListener('offline', updateOnlineStatus);

// ─── SW update detection ───
if ('serviceWorker' in navigator) {
  navigator.serviceWorker.register('/sw.js').then(reg => {
    reg.addEventListener('updatefound', () => {
      const nw = reg.installing;
      nw?.addEventListener('statechange', () => {
        if (nw.state === 'installed' && navigator.serviceWorker.controller) {
          // Frissítés elérhető
          const toast = document.createElement('div');
          toast.style = 'position:fixed;bottom:calc(80px + env(safe-area-inset-bottom));left:50%;transform:translateX(-50%);background:rgba(124,92,252,0.15);border:1px solid rgba(124,92,252,0.3);color:#fff;padding:10px 16px;border-radius:12px;font-size:12px;z-index:9999;backdrop-filter:blur(20px);cursor:pointer;display:flex;align-items:center;gap:8px';
          toast.innerHTML = '🔄 Update available — <strong>tap to reload</strong>';
          toast.onclick = () => { nw.postMessage({ type: 'SKIP_WAITING' }); location.reload(); };
          document.body.appendChild(toast);
        }
      });
    });
  }).catch(() => {});

  // SW takeover után frissítés
  navigator.serviceWorker.addEventListener('controllerchange', () => location.reload());
}

// ─── Keyboard & shortcuts ───
document.addEventListener('keydown', e => {
  if ((e.metaKey || e.ctrlKey) && e.key === 'k') { e.preventDefault(); openSearch(); }
  if ((e.metaKey || e.ctrlKey) && e.key === 'n') { e.preventDefault(); newChat(); }
  if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') { e.preventDefault(); send(); }
  if (e.key === 'Escape') closeSrch();
});

// ─── textarea auto-resize ───
function resize(el) {
  el.style.height = 'auto';
  el.style.height = Math.min(el.scrollHeight, 160) + 'px';
}
$('inp').addEventListener('input', function() { resize(this); });
$('inp').addEventListener('keydown', e => {
  if (e.key === 'Enter' && !e.shiftKey && !e.isComposing) { e.preventDefault(); send(); }
});

// ─── App Lifecycle (iOS background/foreground) ───
document.addEventListener('visibilitychange', () => {
  if (document.visibilityState === 'visible') {
    // Frissítés amikor app előtérbe kerül
    pollAll();
    clearBadge();
  }
});

// ─── Badging futó feladatnál ───
const _origRenderTasks = renderTasks;
renderTasks = function() {
  _origRenderTasks();
  const runCount = Object.values(allTasks).filter(t => t.status === 'running').length;
  if (runCount > 0) setBadge(runCount); else clearBadge();
};

// ─── Page Visibility + Wake Lock futás közben ───
const _origSetRunning = setRunning;
setRunning = function(v) {
  _origSetRunning(v);
  if (v) acquireWakeLock();
  else if (wakeLock) { wakeLock.release(); wakeLock = null; }
};
